css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .intruso-bloque{display: flex; flex-direction: column; gap: 6px;}
.mz .intruso-fila{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;}
.mz .intruso-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px 4px; text-align: center; font-size: 12.5px; font-weight: 700;}
.mz .meses-tabla{width: 100%; border-collapse: collapse;}
.mz .meses-tabla th,.mz .meses-tabla td{border: 1.5px solid var(--bosque); padding: 5px 6px; text-align: center; font-size: 12.5px; height: 30px;}
.mz .meses-tabla th{font-weight: 700; background: #f4f4f4; font-size: 12px;}
.mz .meses-tabla td.lleno{font-weight: 700; background: #fafafa;}
.mz .banco-meses{display: grid; grid-template-columns: repeat(6, 1fr); gap: 5px; margin-bottom: 5px;}
.mz .banco-mes{border: 1.5px dashed #000; border-radius: 6px; padding: 4px 2px; text-align: center; font-size: 11.5px; font-weight: 700; background: #f4f4f4;}
.mz .ordenar-huecos{display: grid; grid-template-columns: repeat(6, 1fr); gap: 5px;}
.mz .ord-hueco-caja{display: flex; flex-direction: column; align-items: center; gap: 2px;}
.mz .ord-num{font-family: sans-serif; font-size: 10.5px; font-weight: 700;}
.mz .ord-hueco{width: 100%; border: 1.5px solid var(--bosque); border-radius: 6px; height: 28px;}
.mz .prob-lista{display: flex; flex-direction: column; gap: 6px;}
.mz .prob{font-size: 13px; line-height: 1.45;}
.mz .hueco-cuadrado{display: inline-block; width: 38px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 5px; vertical-align: middle; margin: 0 4px;}
.mz .hueco-linea{display: inline-block; min-width: 100px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: bottom; margin: 0 3px;}
.mz .prob{line-height: 1.875 !important;}
